struct aiFace {
    unsigned int mNumIndices;
    unsigned int *mIndices;
#ifdef __cplusplus
    aiFace() AI_NO_EXCEPT
            : mNumIndices(0),
              mIndices(nullptr) {}
    ~aiFace() { delete[] mIndices; }
    aiFace(const aiFace &o) :
            mNumIndices(0), mIndices(nullptr) { *this = o; }
    aiFace &operator=(const aiFace &o) {
        if (&o == this) { return *this; }
        delete[] mIndices;
        mNumIndices = o.mNumIndices;
        if (mNumIndices) {
            mIndices = new unsigned int[mNumIndices];
            ::memcpy(mIndices, o.mIndices, mNumIndices * sizeof(unsigned int));
        } else { mIndices = nullptr; }
        return *this;
    }
    bool operator==(const aiFace &o) const {
        if (mIndices == o.mIndices) { return true; }
        if (nullptr != mIndices && mNumIndices != o.mNumIndices) { return false; }
        if (nullptr == mIndices) { return false; }
        for (unsigned int i = 0; i < this->mNumIndices; ++i) {
            if (mIndices[i] != o.mIndices[i]) { return false; }
        }
        return true;
    }
    bool operator!=(const aiFace &o) const { return !(*this == o); }
#endif
};

