struct aiBone {
    C_STRUCT aiString mName;
    unsigned int mNumWeights;
#ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
    C_STRUCT aiNode *mArmature;
    C_STRUCT aiNode *mNode;
#endif
    C_STRUCT aiVertexWeight *mWeights;
    C_STRUCT aiMatrix4x4 mOffsetMatrix;
#ifdef __cplusplus
    aiBone() AI_NO_EXCEPT
            : mName(), mNumWeights(0),
#ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
              mArmature(nullptr), mNode(nullptr),
#endif
              mWeights(nullptr), mOffsetMatrix() {}
    aiBone(const aiBone &other) :
            mName(other.mName), mNumWeights(other.mNumWeights),
#ifndef ASSIMP_BUILD_NO_ARMATUREPOPULATE_PROCESS
              mArmature(nullptr), mNode(nullptr),
#endif
            mWeights(nullptr), mOffsetMatrix(other.mOffsetMatrix) { copyVertexWeights(other); }
    void copyVertexWeights( const aiBone &other ) {
        if (other.mWeights == nullptr || other.mNumWeights == 0) { mWeights = nullptr; mNumWeights = 0; return; }
        mNumWeights = other.mNumWeights;
        if (mWeights) { delete[] mWeights; }
        mWeights = new aiVertexWeight[mNumWeights];
        ::memcpy(mWeights, other.mWeights, mNumWeights * sizeof(aiVertexWeight));
    }
    aiBone &operator = (const aiBone &other) {
        if (this == &other) { return *this; }
        mName = other.mName; mNumWeights = other.mNumWeights; mOffsetMatrix = other.mOffsetMatrix; copyVertexWeights(other); return *this;
    }
    bool operator==(const aiBone &rhs) const {
        if (mName != rhs.mName || mNumWeights != rhs.mNumWeights ) { return false; }
        for (size_t i = 0; i < mNumWeights; ++i) { if (mWeights[i] != rhs.mWeights[i]) { return false; } }
        return true;
    }
    ~aiBone() { delete[] mWeights; }
#endif
};

