        for (unsigned int a = 0; a < AI_MAX_NUMBER_OF_COLOR_SETS; a++) { delete[] mColors[a]; }
        if (mNumBones && mBones) { std::unordered_set<const aiBone *> bones; for (unsigned int a = 0; a < mNumBones; a++) { if (mBones[a]) { bones.insert(mBones[a]); } } for (const aiBone *bone: bones) { delete bone; } delete[] mBones; }
        if (mNumAnimMeshes && mAnimMeshes) { for (unsigned int a = 0; a < mNumAnimMeshes; a++) { delete mAnimMeshes[a]; } delete[] mAnimMeshes; }
