    bool HasTextureCoords(unsigned int index) const { if (index >= AI_MAX_NUMBER_OF_TEXTURECOORDS) { return false; } return (mTextureCoords[index] != nullptr && mNumVertices > 0); }
    unsigned int GetNumUVChannels() const { unsigned int n(0); for (unsigned i = 0; i < AI_MAX_NUMBER_OF_TEXTURECOORDS; i++) { if (mTextureCoords[i]) { ++n; } } return n; }
