struct ASSIMP_API aiNode {
    C_STRUCT aiString mName;
    C_STRUCT aiMatrix4x4 mTransformation;
    C_STRUCT aiNode* mParent;
    unsigned int mNumChildren;
    C_STRUCT aiNode** mChildren;
    unsigned int mNumMeshes;
    unsigned int* mMeshes;
    C_STRUCT aiMetadata* mMetaData;
#ifdef __cplusplus
    aiNode();
    explicit aiNode(const std::string& name);
    ~aiNode();
    inline const aiNode* FindNode(const aiString& name) const { return FindNode(name.data); }
    inline aiNode* FindNode(const aiString& name) { return FindNode(name.data); }
    const aiNode* FindNode(const char* name) const;
    aiNode* FindNode(const char* name);
    const aiNode *findBoneNode(const aiBone *bone) const {
        if (bone == nullptr) { return nullptr; }
        if (mName == bone->mName) { return this; }
        for (unsigned int i = 0; i < mNumChildren; ++i) {
            aiNode *aChild = mChildren[i];
            if (aChild == nullptr) { continue; }
            const aiNode *foundFromChild = nullptr;
            foundFromChild = aChild->findBoneNode(bone);
            if (foundFromChild) { return foundFromChild; }
        }
        return nullptr;
    }
    void addChildren(unsigned int numChildren, aiNode **children);
#endif // __cplusplus
};

