struct aiColor3D {
#ifdef __cplusplus
    aiColor3D() AI_NO_EXCEPT : r(0.0f), g(0.0f), b(0.0f) {}
    aiColor3D(float _r, float _g, float _b) :
            r(_r), g(_g), b(_b) {}
    explicit aiColor3D(float _r) :
            r(_r), g(_r), b(_r) {}
    aiColor3D(const aiColor3D &o) :
            r(o.r), g(o.g), b(o.b) {}

    aiColor3D &operator=(const aiColor3D &o) {
        r = o.r;
        g = o.g;
        b = o.b;
        return *this;
    }

    bool operator==(const aiColor3D &other) const { return r == other.r && g == other.g && b == other.b; }
    bool operator!=(const aiColor3D &other) const { return r != other.r || g != other.g || b != other.b; }
    bool operator<(const aiColor3D &other) const {
        return r < other.r || (r == other.r && (g < other.g || (g == other.g && b < other.b)));
    }
    aiColor3D operator+(const aiColor3D &c) const { return aiColor3D(r + c.r, g + c.g, b + c.b); }
    aiColor3D operator-(const aiColor3D &c) const { return aiColor3D(r - c.r, g - c.g, b - c.b); }
    aiColor3D operator*(const aiColor3D &c) const { return aiColor3D(r * c.r, g * c.g, b * c.b); }
    aiColor3D operator*(ai_real f) const { return aiColor3D(r * f, g * f, b * f); }
    float operator[](unsigned int i) const { return *(&r + i); }
    float &operator[](unsigned int i) {
        if (0 == i) { return r; } else if (1 == i) { return g; } else if (2 == i) { return b; }
        return r;
    }
    bool IsBlack() const {
        static const float epsilon = float(10e-3);
        return std::fabs(r) < epsilon && std::fabs(g) < epsilon && std::fabs(b) < epsilon;
    }
#endif // !__cplusplus

    float r, g, b;
};

struct aiString {
#ifdef __cplusplus
    aiString() AI_NO_EXCEPT :
            length(0), data{'\0'} {
#ifdef ASSIMP_BUILD_DEBUG
        memset(data + 1, 27, AI_MAXLEN - 1);
#endif
    }

    aiString(const aiString &rOther) :
            length(rOther.length), data{'\0'} {
        length = length >= AI_MAXLEN ? AI_MAXLEN - 1 : length;
        memcpy(data, rOther.data, length);
        data[length] = '\0';
    }

    explicit aiString(const std::string &pString) :
            length((ai_uint32)pString.length()), data{'\0'} {
        length = length >= AI_MAXLEN ? AI_MAXLEN - 1 : length;
        memcpy(data, pString.c_str(), length);
        data[length] = '\0';
    }

    void Set(const std::string &pString) {
        if (pString.length() > AI_MAXLEN - 1) {
            return;
        }
        length = (ai_uint32)pString.length();
        memcpy(data, pString.c_str(), length);
        data[length] = 0;
    }

    void Set(const char *sz, size_t maxlen) {
        if (sz == nullptr) {
            return;
        }
        size_t len = 0;
        for (size_t i=0; i<maxlen; ++i) {
            if (sz[i] == '\0') {
                break;
            }
            ++len;
        }
        if (len > AI_MAXLEN - 1) {
            len = AI_MAXLEN - 1;
        }
        length = static_cast<uint32_t>(len);
        memcpy(data, sz, len);
        data[len] = 0;
    }

    aiString &operator=(const aiString &rOther) {
        if (this == &rOther) {
            return *this;
        }

        length = rOther.length;
        if (length > (AI_MAXLEN - 1)) {
            length = static_cast<ai_int32>(AI_MAXLEN - 1);
        }

        memcpy(data, rOther.data, length);
        data[length] = '\0';
        return *this;
    }

    aiString &operator=(const char *sz) {
        Set(sz);
        return *this;
    }

    aiString &operator=(const std::string &pString) {
        Set(pString);
        return *this;
    }

    bool operator==(const aiString &other) const {
        if (length == other.length) {
            return memcmp(data, other.data, length) == 0;
        }
        return false;
    }

    bool operator!=(const aiString &other) const { return !(*this == other); }

    void Append(const char *app) {
        const ai_uint32 len = static_cast<ai_uint32>(::strlen(app));
        if (!len) { return; }
        if (length + len >= AI_MAXLEN) { return; }

        memcpy(&data[length], app, len + 1);
        length += len;
    }

    void Clear() {
        length = 0;
        data[0] = '\0';
#ifdef ASSIMP_BUILD_DEBUG
        memset(data + 1, 27, AI_MAXLEN - 1);
#endif
    }

    const char *C_Str() const { return data; }
    bool Empty() const { return length == 0; }
#endif // !__cplusplus

    ai_uint32 length;
    char data[AI_MAXLEN];
};

